def playlist_total_seconds(apis, access_token, playlist_id):
    songs = apis.spotify.show_playlist(
        playlist_id=playlist_id, access_token=access_token
    ).songs
    return sum(
        apis.spotify.show_song(song_id=song.id).duration for song in songs
    )

def longest_or_shortest_playlist_minutes(apis, main_user, extreme="max"):
    access_token = apis.spotify.access_token_from(main_user)
    playlists = []
    page_index = 0
    while True:
        page = apis.spotify.show_playlist_library(
            access_token=access_token, page_index=page_index
        )
        if not page:
            break
        playlists.extend(page)
        page_index += 1
    durations = [
        playlist_total_seconds(apis, access_token, p.playlist_id) for p in playlists
    ]
    total_seconds = max(durations) if extreme == "max" else min(durations)
    return round(total_seconds / 60)
